class NASOptimizer:
   """TMES: Thompson Mean-Exploitation Search for NAS.

   Novel contribution: Edge-wise Bayesian statistics with Thompson sampling
   and kernel-based exploration bonuses. Maintains population of diverse
   architectures and uses Thompson-weighted edge mutation for efficient
   exploration-exploitation under K=30 budget.
   """

   def __init__(self, api, num_epochs, seed):
       self.api = api
       self.num_epochs = num_epochs
       self.seed = self.seed
       self.best_arch = None
       self.best_val_acc = -1.0
       self.population = []
       self.warmup = 4
       self.seen = set()

       # Edge-wise statistics (6 edges, 5 ops)
       self.edge_mean = np.zeros((NUM_EDGES, NUM_OPS), dtype=np.float32)
       self.edge_std = np.ones((NUM_EDGES, NUM_OPS), dtype=np.float32) * 1.0

   def _update(self, arch, val_acc):
       self.seen.add(tuple(arch))
       self.population.append((arch, val_acc))
       if len(self.population) > 10:
           self.population.pop(0)
       decay = 1.0 - 0.2 * min(1.0, self.api.query_count / 10)
       for edge, op in enumerate(arch):
           self.edge_mean[edge, op] = decay * self.edge_mean[edge, op] + val_acc
           self.edge_std[edge, op] = decay * max(0.05, self.edge_std[edge, op] + 0.06)

   def _thompson_select(self):
       if self.api.query_count < 8:
           arch = random_architecture()
           while tuple(arch) in self.seen:
               arch = random_architecture()
       else:
           scores = np.zeros(NUM_EDGES)
           for edge in range(NUM_EDGES):
               t = np.zeros(NUM_OPS)
               for op in range(NUM_OPS):
                   t[op] = np.random.normal(
                       loc=self.edge_mean[edge, op], scale=self.edge_std[edge, op])
               scores[edge] = t.sum()
           target = np.random.choice(NUM_EDGES, p=scores + 0.1*2)
           op = np.zeros(NUM_OPS)
           for op in range(NUM_OPS):
               op[op] = np.random.normal(
                   loc=self.edge_mean[target, op], scale=self.edge_std[target, op])
               op[op] += np.random.exponential()
           parent = self.population[0] if self.population else (random_architecture(),)
           return mutate_architecture(parent)
       return random_architecture()

   def search_step(self, epoch):
       if epoch < self.warmup or len(self.seen) < 6:
           arch = random_architecture()
           while tuple(arch) in self.seen:
               arch = random_architecture()
       else:
           arch = self._thompson_select()

       if not is_valid_arch(arch):
           arch = random_architecture()

       val_acc = self.api.query_val_accuracy(arch)

       if val_acc > self.best_val_acc:
           self.best_val_acc = val_acc
           self.best_arch = list(arch)

       self._update(arch, val_acc)

       return {
           "best_val_acc": self.best_val_acc,
           "queries": self.api.query_count,
           "transform": "thompson",
       }

   def get_best_architecture(self):
       return self.best_arch

